const g=document.createElement('div');Object.assign(g.style,{display:'grid',gridTemplateColumns:'repeat(3,minmax(100px,180px))',gap:'12px'});stage.appendChild(g);var arcadeMuteButton=document.createElement('button');let arcadeAudio,arcadeMuted=localStorage.getItem('grafana-arcade-muted')!=='false';function renderArcadeMute(){arcadeMuteButton.textContent=arcadeMuted?'AUDIO: OFF':'AUDIO: ON';arcadeMuteButton.style.borderColor=arcadeMuted?'#777d86':'#5794f2';arcadeMuteButton.style.color=arcadeMuted?'#9fa7b3':'#d8d9da'}Object.assign(arcadeMuteButton.style,{position:'absolute',right:'10px',bottom:'10px',zIndex:'3',padding:'6px 8px',border:'1px solid #5794f2',borderRadius:'3px',background:'rgba(17,18,23,.9)',font:'700 10px Roboto Mono,monospace',cursor:'pointer'});stage.appendChild(arcadeMuteButton);arcadeMuteButton.addEventListener('click',e=>{e.stopPropagation();arcadeMuted=!arcadeMuted;localStorage.setItem('grafana-arcade-muted',String(arcadeMuted));if(arcadeMuted&&arcadeAudio)arcadeAudio.suspend();if(!arcadeMuted&&arcadeAudio)arcadeAudio.resume();renderArcadeMute()});renderArcadeMute();function arcadeTone(freq=440,duration=.07,wave='square'){if(arcadeMuted)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!arcadeAudio)arcadeAudio=new Audio();if(arcadeAudio.state==='suspended')arcadeAudio.resume();const oscillator=arcadeAudio.createOscillator(),gain=arcadeAudio.createGain();oscillator.type=wave;oscillator.frequency.value=freq;gain.gain.setValueAtTime(.0001,arcadeAudio.currentTime);gain.gain.exponentialRampToValueAtTime(.045,arcadeAudio.currentTime+.008);gain.gain.exponentialRampToValueAtTime(.0001,arcadeAudio.currentTime+duration);oscillator.connect(gain).connect(arcadeAudio.destination);oscillator.start();oscillator.stop(arcadeAudio.currentTime+duration+.02)}catch(_){/* Sound is optional when browser policy blocks audio. */}}let score=0,res=0,miss=0,ack=[],names=['HighCPU','LokiIngestionLag','MimirCardinalityHigh','TempoDistributorDown','PodCrashLooping','DiskSpaceLow','ErrorBudgetBurn','CertificateExpiring'];metric('alerts_resolved_total','0');metric('alerts_missed_total','0');metric('current_incidents','0');metric('mean_time_to_ack','0ms');metric('score','0');state('ACK FIRING ALERTS');for(let i=0;i<9;i++){let b=document.createElement('button');b.textContent='NORMAL';Object.assign(b.style,{height:'100px',background:'#181b1f',color:'#73bf69',border:'1px solid #34373d',font:'bold 12px monospace'});b.onclick=()=>{if(b.dataset.t){let t=performance.now()- +b.dataset.t;ack.push(t);res++;score+=10;arcadeTone(720,.08,'sine');b.textContent='ACKNOWLEDGED';b.style.color='#5794f2';delete b.dataset.t;setTimeout(()=>{b.textContent='NORMAL';b.style.color='#73bf69'},300)}};g.appendChild(b)}let bs=[...g.children];const alertTimer=arcadeInterval(()=>{if(!root.isConnected){clearInterval(alertTimer);try{if(arcadeAudio)arcadeAudio.close()}catch(_){ }return}let b=bs[Math.random()*bs.length|0];if(b.dataset.t){miss++;score-=5;arcadeTone(130,.16,'sawtooth')}b.dataset.t=performance.now();b.textContent='FIRING\n'+names[Math.random()*names.length|0];b.style.color='#f2495c';set('alerts_resolved_total',res);set('alerts_missed_total',miss);set('current_incidents',bs.filter(x=>x.dataset.t).length);set('mean_time_to_ack',(ack.reduce((a,b)=>a+b,0)/Math.max(1,ack.length)|0)+'ms');set('score',score)},1200);
